        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "wrtrptMaindocTpCd") ?? '') : '');
        if (v === '1') { return String((dl && dl.getCellData ? dl.getCellData(r, "lstChgDdtm") : '') ?? ''); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.lstChgDdtm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_disclsTitle
 * @description grd doc Page List fmt discls Title 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
