/**
 * @method
 * @name grd_docPageList_fillAct
 * @description grd doc Page List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.fillAct' });
    }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    if ($c.util.getComponent('cal_searchBeginDd').getValue()> $c.util.getComponent('cal_searchEndDd').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    /* 수동 전환 필요: searchForm.submit() — as-is 자기제출(action 없음), 대체 tx 미정 */ await $c.win.alert("이 동작은 아직 전환되지 않았습니다(as-is 폼 «searchForm» 자기제출 — 대체 서버 호출 미정).");
};

/**
 * @method
 * @name esgDisclosurePreview
 * @description esg Disclosure Preview 처리
 * @param {*} applNo applNo
 * @param {*} disclsDocNo disclsDocNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.esgDisclosurePreview = async function (applNo, disclsDocNo) {
    await $c.win.alert("해당 공시는 미리보기가 제공되지 않습니다. 제출 후 KIND 조회시스템을 통해 확인해주세요.");
};

/**
 * @method
 * @name esgDisclosureCancel
 * @description esg Disclosure Cancel 처리
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.esgDisclosureCancel = async function (applNo) {
    if (await $c.win.confirm('보고서 생성을 취소하시겠습니까? (취소 이후 편집기 임시보관함에서 기 작성내용 확인 가능)')) {
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('applNo', applNo);
        await scwin.tx_esgDisclosureCancel();
    }
};

/**
 * @method
 * @name esgEngSelectPop
 * @description esg Eng Select Pop 처리
 * @param {*} applNo applNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} langTpCd langTpCd
 * @param {String} disclsAcptTpCd disclsAcptTpCd
 * @param {String} mainFormNm mainFormNm
 * @param {String} disclsSubmitCorpIsurCd disclsSubmitCorpIsurCd
 * @param {*} disclsTitle disclsTitle
 * @param {String} subcomDisclsYn subcomDisclsYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.esgEngSelectPop = async function (applNo, formCd, formVer, langTpCd, disclsAcptTpCd, mainFormNm, disclsSubmitCorpIsurCd, disclsTitle, subcomDisclsYn) {
    if (scwin.checkRepFormVerYn(formCd, formVer)) {
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('applNo', applNo);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('mainFormNm', mainFormNm);
        $c.util.getComponent("slc_formCd").setValue(formCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('disclsAcptTpCd', disclsAcptTpCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('disclsSubmitCorpIsurCd', disclsSubmitCorpIsurCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('langTpCd', langTpCd);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('disclsTitle', disclsTitle);
        $c.util.getComponent('dma_esgDisclosureCancelReq').set('subcomDisclsYn', subcomDisclsYn);
        if (disclsAcptTpCd === 'F') {
            const url = '/ui/jsp/JLDFIL00000.xml';
            await $c.win.openPopup(url, { id: "_blank", width: "700", height: "740", scrollbars: true, resizable: true, type: "pageFramePopup" }, { method: "engDisclsProcessInspection", applNo: applNo, langTpCd: langTpCd, formCd: formCd, formVer: formVer, disclsAcptTpCd: disclsAcptTpCd });
        } else {
            if (disclsAcptTpCd === 'M' || disclsAcptTpCd === 'U' || disclsAcptTpCd === 'A') {
                await scwin.tx_esgEngSelectPop('/esg/writeESGSubmitInfoForm.do?method=writeEngSubmitInfo');
            }
        }
    } else {
        await $c.win.alert('해당 공시는 이전 서식버전이므로 제출할 수 없습니다. \'취소\' 후 최신 서식 버전으로 다시 보고서를 생성해 주세요.');
    }
};

/**
 * @method
 * @name checkRepFormVerYn
 * @description check Rep Form Ver Yn 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {void}
 * @hidden N
 */
scwin.checkRepFormVerYn = function (formCd, formVer) {
    const xhr = new XMLHttpRequest();
    const url = '/esg/searchESGDisclosureForm.do?method=checkRepFormVerYn&' + 'formCd=' + formCd + '&formVer=' + formVer;
    xhr.open('GET', url, false);
    xhr.setRequestHeader('Cache-Control', 'no-cache');
    xhr.setRequestHeader('Pragma', 'no-cache');
    xhr.setRequestHeader('If-Modified-Since', '0');
    xhr.send();
    if (xhr.status === 200) {
        const result = (typeof xhr.response === "string" ? (typeof xhr.response === "string" ? JSON.parse(xhr.response) : xhr.response) : xhr.response);
        if (result.repFormVerYn === 'Y') {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name setEngOrgnPopupFlag
 * @description set Eng Orgn Popup Flag 처리
 * @param {String} strFlag strFlag
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setEngOrgnPopupFlag = async function (strFlag) {
    if (strFlag === 'Y') {
        await scwin.tx_fn_setEngOrgnPopupFlag('/esg/writeESGSubmitInfoForm.do?method=writeEngSubmitInfo');
    } else {
        await $c.win.alert('영문원공시접수번호 업데이트 중 오류가 발생하였습니다. 시스템 관리자에게 문의하세요.');
    }
};

